#!/usr/bin/env python3
"""Helper script to process Gateway API manifests."""

import sys

_GATEWAY_API_HEADER = """# Generated by update.sh. DO NOT EDIT!
# ---------------------------------------------------------
# Gateway API Custom Resource Definitions (CRDs) - Standard Channel
# ---------------------------------------------------------
"""


def process_gateway_api(gateway_api_file: str) -> None:
  """Processes Gateway API CRDs in-place.

  Args:
    gateway_api_file: Path to the gateway api CRDs file.
  """
  with open(gateway_api_file, "r", encoding="utf-8") as f:
    gapi_raw = f.read()

  gapi_docs = gapi_raw.split("\n---\n")
  processed_gapi = []
  for doc_str in gapi_docs:
    cleaned = doc_str.strip()
    if not cleaned:
      continue
    # Skip header if it was already processed
    if cleaned.startswith("# Generated"):
      continue
    processed_gapi.append(cleaned)

  with open(gateway_api_file, "w", encoding="utf-8") as f:
    # Write header followed by --- to keep it separate from the first CRD
    f.write(
        _GATEWAY_API_HEADER + "---\n" + "\n---\n".join(processed_gapi) + "\n"
    )


def main() -> None:
  if len(sys.argv) < 2:
    print(f"Usage: {sys.argv[0]} <gateway_api_file>", file=sys.stderr)
    sys.exit(1)
  process_gateway_api(sys.argv[1])


if __name__ == "__main__":
  main()
